package com.deathrecap;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Who attacked the player in a recap: an NPC or, in PvP, another player.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class Attacker
{
	private String name;
	/** Combat level, or 0 when unknown. */
	private int combatLevel;
	/** True for another player. */
	private boolean player;
}

package com.deathrecap;

import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.Queue;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.DrawManager;

/**
 * Captures the death screenshot and keeps a rolling buffer of full-size frames for the replay GIF, so
 * text in both is as readable as in the game. Frames are copied on the client thread into one of two
 * reusable buffers and compressed on a dedicated thread. Screenshots and GIFs are written on a second
 * thread, so a slow GIF (say, a close call's just before a death) never stops recording. If the frame
 * thread falls behind, frames are skipped.
 */
@Slf4j
class DeathCapture
{
	/** How long recording continues after the death, so the replay shows the death animation. */
	static final long AFTER_DEATH_MS = 2000;
	private static final int BUFFERS = 2;
	/** The last frame is held this long (hundredths of a second) before the GIF loops. */
	private static final int FINAL_FRAME_DELAY = 150;

	private static final class Frame
	{
		final long time;
		final byte[] jpeg;

		Frame(long time, byte[] jpeg)
		{
			this.time = time;
			this.jpeg = jpeg;
		}
	}

	/** Told the record, the saved file name and, for replays, when each frame was captured relative to the death in ms. */
	interface Saved
	{
		void saved(DeathRecord record, String name, int[] times);
	}

	private final Client client;
	private final DrawManager drawManager;
	private final DeathRecapConfig config;
	private final DeathStore store;
	private final Runnable frameListener = this::onFrame;
	private final Deque<Frame> frames = new ArrayDeque<>();
	/** Copy buffers not currently being compressed; at most {@link #BUFFERS} exist. */
	private final Queue<BufferedImage> spare = new ConcurrentLinkedQueue<>();
	private final AtomicInteger buffers = new AtomicInteger();

	/** Compresses frames and takes each clip when it is due. */
	private ScheduledExecutorService worker;
	/** Writes screenshots and GIFs. */
	private ExecutorService writer;
	private long lastRequest;
	private boolean requestPending;

	DeathCapture(Client client, DrawManager drawManager, DeathRecapConfig config, DeathStore store)
	{
		this.client = client;
		this.drawManager = drawManager;
		this.config = config;
		this.store = store;
	}

	void start()
	{
		worker = Executors.newSingleThreadScheduledExecutor(r ->
		{
			Thread t = new Thread(r, "death-recap-frames");
			t.setDaemon(true);
			return t;
		});
		writer = Executors.newSingleThreadExecutor(r ->
		{
			Thread t = new Thread(r, "death-recap-media");
			t.setDaemon(true);
			return t;
		});
		drawManager.registerEveryFrameListener(frameListener);
	}

	void stop()
	{
		drawManager.unregisterEveryFrameListener(frameListener);
		if (worker != null)
		{
			worker.shutdownNow();
			worker = null;
		}
		if (writer != null)
		{
			writer.shutdownNow();
			writer = null;
		}
		clear();
	}

	void clear()
	{
		synchronized (frames)
		{
			frames.clear();
		}
		// Buffers still being compressed come back to spare afterwards and are counted until dropped here.
		while (spare.poll() != null)
		{
			buffers.decrementAndGet();
		}
	}

	/**
	 * Called on the client thread when the local player dies or has a close call. Each callback runs on
	 * the media thread once its file has been written.
	 */
	void captureDeath(long accountHash, DeathRecord record, Saved onScreenshot, Saved onReplay)
	{
		captureDeath(accountHash, record, AFTER_DEATH_MS, onScreenshot, onReplay);
	}

	/** As above, with the replay running {@code afterMs} past the record's timestamp. */
	void captureDeath(long accountHash, DeathRecord record, long afterMs, Saved onScreenshot, Saved onReplay)
	{
		ScheduledExecutorService w = worker;
		ExecutorService out = writer;
		if (w == null || out == null || !config.saveToDisk())
		{
			return;
		}
		long deathTime = record.getTimestamp();

		if (config.saveScreenshot())
		{
			drawManager.requestNextFrameListener(image ->
			{
				BufferedImage copy = copy(image);
				String name = deathTime + ".png";
				execute(out, () ->
				{
					try
					{
						store.writePng(accountHash, name, copy);
						onScreenshot.saved(record, name, null);
					}
					catch (Exception e)
					{
						log.warn("Unable to save death screenshot", e);
					}
				});
			});
		}

		if (config.recordReplay())
		{
			long from = deathTime - config.replaySeconds() * 1000L;
			long to = deathTime + afterMs;
			// The clip is taken on the frame thread when it's due, before older frames are dropped, and
			// written on the media thread, which may still be busy with an earlier GIF.
			w.schedule(() ->
			{
				List<Frame> clip = new ArrayList<>();
				synchronized (frames)
				{
					for (Frame f : frames)
					{
						if (f.time >= from && f.time <= to)
						{
							clip.add(f);
						}
					}
				}
				log.debug("Replay clip: {} frames, {} to {} ms from the death", clip.size(),
					clip.isEmpty() ? 0 : clip.get(0).time - deathTime, clip.isEmpty() ? 0 : clip.get(clip.size() - 1).time - deathTime);
				if (clip.size() >= 2)
				{
					execute(out, () -> writeReplay(accountHash, record, deathTime, clip, onReplay));
				}
			}, afterMs + 100, TimeUnit.MILLISECONDS);
		}
	}

	private void writeReplay(long accountHash, DeathRecord record, long deathTime, List<Frame> clip, Saved onReplay)
	{
		String name = deathTime + ".gif";
		try
		{
			store.writeGif(accountHash, name, i -> FrameCodec.decode(clip.get(i).jpeg), delays(clip));
			int[] times = new int[clip.size()];
			for (int i = 0; i < times.length; i++)
			{
				times[i] = (int) (clip.get(i).time - deathTime);
			}
			onReplay.saved(record, name, times);
		}
		catch (Exception e)
		{
			log.warn("Unable to save death replay", e);
		}
	}

	private static void execute(ExecutorService executor, Runnable task)
	{
		try
		{
			executor.execute(task);
		}
		catch (RejectedExecutionException e)
		{
			// Shutting down.
		}
	}

	private void onFrame()
	{
		if (!config.recordReplay() || !config.saveToDisk() || client.getGameState() != GameState.LOGGED_IN)
		{
			if (!frames.isEmpty())
			{
				clear();
			}
			return;
		}
		long now = System.currentTimeMillis();
		long interval = 1000L / config.replayFps();
		// If a requested frame never arrived (e.g. the window was minimised), ask again.
		if (now - lastRequest < interval || (requestPending && now - lastRequest < 1000))
		{
			return;
		}
		lastRequest = now;
		requestPending = true;
		drawManager.requestNextFrameListener(image ->
		{
			requestPending = false;
			ScheduledExecutorService w = worker;
			BufferedImage copy = w == null ? null : buffer(image.getWidth(null), image.getHeight(null));
			if (copy == null)
			{
				return;
			}
			Graphics2D g = copy.createGraphics();
			g.drawImage(image, 0, 0, null);
			g.dispose();
			long time = System.currentTimeMillis();
			long keep = config.replaySeconds() * 1000L + AFTER_DEATH_MS + 500;
			try
			{
				w.execute(() ->
				{
					try
					{
						Frame frame = new Frame(time, FrameCodec.encode(copy));
						synchronized (frames)
						{
							frames.addLast(frame);
							while (!frames.isEmpty() && frames.peekFirst().time < time - keep)
							{
								frames.pollFirst();
							}
						}
					}
					catch (Exception e)
					{
						log.debug("Unable to compress replay frame", e);
					}
					finally
					{
						spare.offer(copy);
					}
				});
			}
			catch (RejectedExecutionException e)
			{
				// Shutting down.
				spare.offer(copy);
			}
		});
	}

	/** A free copy buffer of the given size, or null if both are busy. */
	private BufferedImage buffer(int width, int height)
	{
		BufferedImage b;
		while ((b = spare.poll()) != null)
		{
			if (b.getWidth() == width && b.getHeight() == height)
			{
				return b;
			}
			// The window was resized; replace this buffer.
			buffers.decrementAndGet();
		}
		if (buffers.incrementAndGet() > BUFFERS)
		{
			buffers.decrementAndGet();
			return null;
		}
		return new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
	}

	private static BufferedImage copy(Image image)
	{
		BufferedImage out = new BufferedImage(image.getWidth(null), image.getHeight(null), BufferedImage.TYPE_INT_RGB);
		Graphics2D g = out.createGraphics();
		g.drawImage(image, 0, 0, null);
		g.dispose();
		return out;
	}

	/** Uses the real time between captured frames so the replay plays back at game speed. */
	static int[] delays(List<Frame> clip)
	{
		int[] delays = new int[clip.size()];
		for (int i = 0; i < clip.size() - 1; i++)
		{
			long ms = clip.get(i + 1).time - clip.get(i).time;
			delays[i] = (int) Math.max(2, Math.min(100, Math.round(ms / 10.0)));
		}
		delays[delays.length - 1] = FINAL_FRAME_DELAY;
		return delays;
	}
}

package com.deathrecap;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(DeathRecapConfig.GROUP)
public interface DeathRecapConfig extends Config
{
	String GROUP = "death-recap";

	@ConfigSection(
		name = "Screenshot & replay",
		description = "Save a screenshot and an animated replay with each recap",
		position = 10
	)
	String MEDIA = "media";

	@Range(min = 5, max = 60)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "recapSeconds",
		name = "Recap length",
		description = "How far back before a death to record",
		position = 1
	)
	default int recapSeconds()
	{
		return 15;
	}

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show on-screen recap",
		description = "Show a short recap on screen after you die",
		position = 2
	)
	default boolean showOverlay()
	{
		return true;
	}

	@Range(min = 3, max = 120)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "overlaySeconds",
		name = "On-screen duration",
		description = "How long the on-screen recap stays up",
		position = 3
	)
	default int overlaySeconds()
	{
		return 15;
	}

	@ConfigItem(
		keyName = "chatSummary",
		name = "Chat summary",
		description = "Post a one-line summary in chat after you die",
		position = 4
	)
	default boolean chatSummary()
	{
		return true;
	}

	@ConfigItem(
		keyName = "recordAttacks",
		name = "Record attack animations",
		description = "Include attackers' attack animations and incoming projectiles in the timeline",
		position = 5
	)
	default boolean recordAttacks()
	{
		return true;
	}

	@ConfigItem(
		keyName = "saveToDisk",
		name = "Save recaps",
		description = "Keep recaps between sessions",
		position = 6
	)
	default boolean saveToDisk()
	{
		return true;
	}

	@Range(min = 1, max = 200)
	@ConfigItem(
		keyName = "maxSaved",
		name = "Recaps to keep",
		description = "Older recaps are removed once this many are stored",
		position = 7
	)
	default int maxSaved()
	{
		return 25;
	}

	@ConfigItem(
		keyName = "closeCalls",
		name = "Record close calls",
		description = "Save a recap when a hit takes you very low and you survive. It's made after the fight"
			+ " calms down; nothing is shown while you're in combat.",
		position = 8
	)
	default boolean closeCalls()
	{
		return true;
	}

	@Range(min = 5, max = 50)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "closeCallPercent",
		name = "Close call below",
		description = "Counts as a close call when a hit takes your HP to this share of your maximum or lower",
		position = 9
	)
	default int closeCallPercent()
	{
		return 15;
	}

	@ConfigItem(
		keyName = "shareCardLayout",
		name = "Share card layout",
		description = "The layout listed first under the Share card button. Wide: screenshot with the recap below."
			+ " Side panel: recap beside the screenshot. Tall: stacked, for phones. Recap only: no screenshot.",
		section = MEDIA,
		position = 15
	)
	default ShareCardLayout shareCardLayout()
	{
		return ShareCardLayout.WIDE;
	}

	@ConfigItem(
		keyName = "saveScreenshot",
		name = "Screenshot on death",
		description = "Save a screenshot of the moment you die with the recap. Needs 'Save recaps'.",
		section = MEDIA,
		position = 11
	)
	default boolean saveScreenshot()
	{
		return true;
	}

	@ConfigItem(
		keyName = "recordReplay",
		name = "Death replay (GIF)",
		description = "Keep a rolling buffer of the last few seconds at full game size and save it as an animated GIF"
			+ " when you die. Uses about 20-80 MB of memory and some CPU on a background thread. Needs 'Save recaps'.",
		section = MEDIA,
		position = 12
	)
	default boolean recordReplay()
	{
		return false;
	}

	@Range(min = 3, max = 15)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "replaySeconds",
		name = "Replay length",
		description = "Seconds of gameplay before the death to include; about 2 more seconds after it are added",
		section = MEDIA,
		position = 13
	)
	default int replaySeconds()
	{
		return 8;
	}

	@Range(min = 2, max = 10)
	@ConfigItem(
		keyName = "replayFps",
		name = "Replay frame rate",
		description = "Frames per second captured for the replay",
		section = MEDIA,
		position = 14
	)
	default int replayFps()
	{
		return 6;
	}

	@ConfigItem(
		keyName = "clipHotkey",
		name = "Save clip hotkey",
		description = "Saves the last few seconds as a recap, with a replay, without dying. Needs Save recaps and Death replay on.",
		section = MEDIA,
		position = 15
	)
	default Keybind clipHotkey()
	{
		return Keybind.NOT_SET;
	}
}

package com.deathrecap;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Instant;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

class DeathRecapOverlay extends OverlayPanel
{
	private static final int RECENT_HITS = 5;
	private static final int FINDINGS = 3;
	private static final int LOST_ITEMS = 3;

	private final DeathRecapPlugin plugin;

	@Inject
	DeathRecapOverlay(DeathRecapPlugin plugin)
	{
		super(plugin);
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(220, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		DeathRecord record = plugin.getOverlayRecord();
		RecapAnalyzer.Summary summary = plugin.getOverlaySummary();
		if (record == null || summary == null)
		{
			return null;
		}
		if (Instant.now().isAfter(plugin.getOverlayUntil()))
		{
			plugin.hideOverlay();
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Killed by " + RecapAnalyzer.label(record, summary.getKiller()))
			.color(new Color(0xFF, 0x60, 0x60))
			.build());
		RecapEvent blow = summary.getKillingBlow();
		if (blow != null && blow.getWeapon() != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("With")
				.right(blow.getWeapon())
				.rightColor(Color.WHITE)
				.build());
		}

		if (record.getState() != null)
		{
			ItemsOnDeath.Result items = ItemsOnDeath.compute(record.getState());
			panelComponent.getChildren().add(LineComponent.builder()
				.left(items.getAtRisk().isEmpty() ? "Nothing lost" : "Lost (estimate)")
				.right(items.getAtRisk().isEmpty() ? "" : ItemsOnDeath.gp(items.getRiskValue()) + " gp")
				.leftColor(HpGraph.FOOD)
				.rightColor(HpGraph.FOOD)
				.build());
			items.getAtRisk().stream().limit(LOST_ITEMS).forEach(s ->
				panelComponent.getChildren().add(LineComponent.builder()
					.left("  " + RecapText.stack(s))
					.leftColor(Color.LIGHT_GRAY)
					.right(s.getPrice() > 0 ? ItemsOnDeath.gp(s.getPrice() * s.getQuantity()) : "")
					.build()));
		}

		List<RecapEvent> hits = record.getEvents().stream()
			.filter(RecapEvent::isDamage)
			.sorted(Comparator.comparingInt(RecapEvent::getTick).reversed())
			.limit(RECENT_HITS)
			.collect(Collectors.toList());
		for (RecapEvent e : hits)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(RecapText.offset(e.getTick(), record.getDeathTick()) + " " + e.getSource())
				.right(String.valueOf(e.getAmount()))
				.rightColor(e.getType() == RecapEvent.Type.HIT ? Color.WHITE : new Color(0x6C, 0xC0, 0x4A))
				.build());
		}

		// The first finding repeats the killing blow shown above, so skip it.
		summary.getFindings().stream().skip(1).limit(FINDINGS).forEach(f ->
			panelComponent.getChildren().add(LineComponent.builder()
				.left(f)
				.leftColor(Color.LIGHT_GRAY)
				.build()));

		return super.render(graphics);
	}
}

